void test (int n) {
  if (n==0x12345678)
     crash();
}
needs 2^32 attempts
In the worst case
Make it easier to fuzz
void test (int n) {
  int dummy = 0;
  char *p = (char *)&n;
  if (p[3]==0x12) dummy++;
  if (p[2]==0x34) dummy++;
  if (p[1]==0x56) dummy++;
  if (p[0]==0x56) dummy++;
  if (dummy==4)
    crash();
}

